final class _ChatGptCodexSession {
  _ChatGptCodexSession(
    this.model,
    this.context,
    this.encodedCredentials,
    this.onCredentialsRefreshed,
    this.events,
    this.state,
    this.cancelToken,
    this.client,
  );

  final Model model;
  final Context context;
  final String encodedCredentials;
  final ChatGptCredentialsPersist? onCredentialsRefreshed;
  final AssistantMessageEventStream events;
  final ProviderStreamState state;
  final CancelToken? cancelToken;
  final http.Client client;
  final _SseAccumulator _sse = _SseAccumulator();
  final CodexCookieJar _cookies = CodexCookieJar();

  /// Stable per-turn Codex telemetry ids; retries within the turn reuse
  /// them so the backend can correlate attempts.
  final String _sessionId = uuidv7();
  final String _threadId = uuidv7();

  /// Cookie header value captured before the latest request went out.
  String? _cookiesBeforeRequest;

  Future<void> run() async {
    // Issue #1704: the full OAuth blob is the primary shape, but a queue
    // entry (or env var) may carry a plain Bearer access token. Decode
    // failure degrades to raw-bearer use: no proactive refresh, and a 401
    // surfaces as the auth death it is (a refresh cannot work without a
    // refresh token) so the queue fails over instead of throwing
    // FormatException before the first request.
    final decoded = tryDecodeChatGptCredentials(encodedCredentials);
    final rawBearer = decoded == null;
    var credentials =
        decoded ??
        ChatGptOAuthCredentials(
          accessToken: [REDACTED:Sensitive Value],
          refreshToken: '',
          idToken: '',
        );
    if (!rawBearer && credentials.needsRefresh(DateTime.now())) {
      // Proactive: the access token is at/past expiry minus skew.
      credentials = await _refreshCredentials(credentials);
    }
    var refreshedOn401 = false;
    var replayedCookies = false;
    var response = await _request(credentials);
    while (true) {
      if (response.statusCode == 401 && !refreshedOn401 && !rawBearer) {
        // Reactive backstop: refresh once, persist, retry.
        refreshedOn401 = true;
        await response.stream.drain();
        credentials = await _refreshCredentials(credentials);
        response = await _request(credentials);
        continue;
      }
      if (!_isCloudflareChallenge(response)) break;
      await response.stream.drain();
      if (replayedCookies || !_learnedCookies()) {
        throw StateError(
          'ChatGPT responded with a Cloudflare challenge that cookie '
          'replay could not clear. Re-authenticate with '
          '`fa /provider chatgpt oauth` or retry later.',
        );
      }
      // Replay the freshly learned Cloudflare cookies once.
      replayedCookies = true;
      response = await _request(credentials);
    }
    if (response.statusCode != 200) {
      throw await _httpError(response);
    }
    events.push(StartEvent(partial: state.snapshot()));
    await _consumeSseLines(response);
    _sse.finish(_handleEvent);
    _finish();
  }

  /// Consumes the SSE byte stream line by line under the stream-idle
  /// watchdog (issue #1036 review round 1): codex bypasses the shared
  /// [createSseIterator], so without this a connected-but-silent endpoint
  /// hung the turn forever after headers arrived. No decoded line for
  /// [effectiveProviderStreamIdleTimeout] errors the turn (the resolver can
  /// fail over) and the finally-cancel detaches the byte pipeline — the
  /// issue-#921 safe abandonment this bypass would otherwise lose. The
  /// cancel token detaches at once too (issue #1121 review round 1): an
  /// abort during a silent stretch must not wait for the next line or the
  /// idle watchdog.
  Future<void> _consumeSseLines(http.StreamedResponse response) async {
    // Issue #1554, review round 1: the model's request-scoped idle window
    // wins; WITHOUT a model override the same URL-keyed tuning table
    // createSseIterator consults applies (a streamIdleTimeoutMs-only
    // registry entry must scope the codex bypass too, not just the shared
    // iterator path).
    final tunedIdle = response.request?.url == null
        ? effectiveProviderStreamIdleTimeout
        : providerStreamIdleTimeoutForUrl(response.request!.url);
