final class _ChatGptCodexSession {
  _ChatGptCodexSession(
    this.model,
    this.context,
    this.encodedCredentials,
    this.onCredentialsRefreshed,
    this.events,
    this.state,
    this.cancelToken,
    this.client,
  );

  final Model model;
  final Context context;
  final String encodedCredentials;
  final ChatGptCredentialsPersist? onCredentialsRefreshed;
  final AssistantMessageEventStream events;
  final ProviderStreamState state;
  final CancelToken? cancelToken;
  final http.Client client;
  final _SseAccumulator _sse = _SseAccumulator();
  final CodexCookieJar _cookies = CodexCookieJar();

  /// Stable per-turn Codex telemetry ids; retries within the turn reuse
  /// them so the backend can correlate attempts.
  final String _sessionId = uuidv7();
  final String _threadId = uuidv7();

  /// Cookie header value captured before the latest request went out.
  String? _cookiesBeforeRequest;

  Future<void> run() async {
    // Issue #1704: the full OAuth blob is the primary shape, but a queue
    // entry (or env var) may carry a plain Bearer access token. Decode
    // failure degrades to raw-bearer use: no proactive refresh, and a 401
    // surfaces as the auth death it is (a refresh cannot work without a
    // refresh token) so the queue fails over instead of throwing
    // FormatException before the first request.
    final decoded = tryDecodeChatGptCredentials(encodedCredentials);
    final rawBearer = decoded == null;
    var credentials =
        decoded ??
        ChatGptOAuthCredentials(
          accessToken: [REDACTED:Sensitive Value],
          refreshToken: '',
          idToken: '',
        );
