  /// supported value today (gh-1681 Gap 2).
  final String format;

  /// `--output <path>` (export only): where the export is written;
  /// stdout when null.
  final String? output;

  /// `--at N` (view only): the snapshot as it stood at record N.
  final int? at;
}

