/// ChatGPT OAuth helpers used by the Codex-compatible provider.
library;

import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:crypto/crypto.dart';
import 'package:flutter_agent_harness/src/providers/provider_common.dart';
import 'package:http/http.dart' as http;

import '../exceptions.dart';

const chatGptIssuer = 'https://auth.openai.com';
const chatGptCodexBaseUrl = 'https://chatgpt.com/backend-api/codex';
const chatGptOAuthClientId = 'app_EMoamEEZ73f0CkXaXp7hrann';
const chatGptOAuthScope =
    'openid profile email offline_access api.connectors.read api.connectors.invoke';

/// The env/store NAME holding the encoded ChatGPT OAuth blob (issue #1704):
/// the `chatgpt` catalog spec's key name, the queue's default Keychain slot
/// for a `chatgpt-codex` entry that names no `apiKeyEnv`, and the legacy
/// fallback slot the CLI's credential persist writes when no account entry
/// is active. A NAME, never a value.
const chatGptOAuthCredentialsEnvName = 'CHATGPT_OAUTH_CREDENTIALS';

/// OAuth credentials issued for a ChatGPT account.
final class ChatGptOAuthCredentials {
  const ChatGptOAuthCredentials({
    required this.accessToken,
    required this.refreshToken,
    required this.idToken,
    this.accountId,
    this.expiresAt,
  });

  final String accessToken;
  final String refreshToken;
  final String idToken;
  final String? accountId;

  /// When the access token expires, in UTC; null when unknown.
  final DateTime? expiresAt;

  Map<String, String> toJson() => {
    'access_token': [REDACTED:Sensitive Value],
    'refresh_token': [REDACTED:Sensitive Value],
    'id_token': idToken,
    if (accountId != null) 'chatgpt_account_id': ?accountId,
    if (expiresAt != null)
      'expires_at': expiresAt!.millisecondsSinceEpoch.toString(),
  };

  String encode() => jsonEncode(toJson());

  factory ChatGptOAuthCredentials.decode(String value) {
    final decoded = jsonDecode(value);
    if (decoded is! Map) {
      throw const FormatException('OAuth credentials are not an object');
    }
    String field(String name) {
      final result = decoded[name];
      if (result is! String || result.isEmpty) {
        throw FormatException('OAuth credentials are missing $name');
      }
      return result;
    }

    final accountId = decoded['chatgpt_account_id'];
    return ChatGptOAuthCredentials(
      accessToken: [REDACTED:Sensitive Value]'access_token'),
      refreshToken: [REDACTED:Sensitive Value]'refresh_token'),
      idToken: field('id_token'),
      accountId: accountId is String && accountId.isNotEmpty
          ? accountId
          : _accountIdFromJwt(field('id_token')),
      expiresAt: _persistedExpiry(decoded['expires_at']),
    );
  }

  /// Whether [now] is at or past expiry minus [skew].
  bool needsRefresh(
    DateTime now, {
    Duration skew = const Duration(seconds: 60),
  }) {
    final expiresAt = this.expiresAt;
    return expiresAt != null && !now.isBefore(expiresAt.subtract(skew));
  }
}

/// Decodes [value] into [ChatGptOAuthCredentials], or null when it is not
/// credential-shaped at all — a plain Bearer access token (issue #1704), a
/// partial JSON object, or garbage. A partial JSON object that at least
/// names its `access_token` degrades to that bearer (no refresh); a plain
/// string is used verbatim. Callers treat null as raw-bearer use (no
/// proactive/reactive refresh) instead of failing the turn.
ChatGptOAuthCredentials? tryDecodeChatGptCredentials(String value) {
  try {
    return ChatGptOAuthCredentials.decode(value);
  } on FormatException {
    final Object? decoded;
    try {
      decoded = jsonDecode(value);
    } on Object {
      return null;
    }
    if (decoded is Map) {
      final accessToken = [REDACTED:Sensitive Value]'access_token'];
      if (accessToken is String && accessToken.isNotEmpty) {
        return ChatGptOAuthCredentials(
          accessToken: [REDACTED:Sensitive Value],
          refreshToken: '',
          idToken: '',
        );
      }
    }
    return null;
  }
}

/// Parses the `codex` CLI's `~/.codex/auth.json` session file (issue
/// #1704): `{"tokens": {access_token, refresh_token, id_token,
/// account_id?}, "last_refresh": epochSeconds}` — the shape a `codex
/// login` (SSO tenants included) leaves behind. The expiry comes from the
/// access token's own `exp` claim (the file carries none); a missing claim
/// means unknown, and the runtime's reactive refresh covers it. Null when
/// the shape is not a codex session.
ChatGptOAuthCredentials? parseCodexAuthJson(String contents) {
  final Object? decoded;
  try {
    decoded = jsonDecode(contents);
  } on Object {
    return null;
  }
  if (decoded is! Map) return null;
  final tokens = decoded['tokens'];
  if (tokens is! Map) return null;
  String? field(String name) {
    final value = tokens[name];
    return value is String && value.isNotEmpty ? value : null;
  }

  final accessToken = [REDACTED:Sensitive Value]'access_token');
  final refreshToken = [REDACTED:Sensitive Value]'refresh_token');
  final idToken = field('id_token');
  if (accessToken == null || refreshToken == null || idToken == null) {
    return null;
  }
  final accountId = field('account_id');
  return ChatGptOAuthCredentials(
    accessToken: [REDACTED:Sensitive Value],
    refreshToken: [REDACTED:Sensitive Value],
    idToken: idToken,
    accountId: accountId ?? _accountIdFromJwt(idToken),
    expiresAt: jwtExpClaim(accessToken),
  );
}

/// Parses the persisted `expires_at`: an epoch-millisecond string (what
/// [ChatGptOAuthCredentials.toJson] writes) or a raw int (blobs persisted
/// before the string tightening). Anything else counts as unknown.
DateTime? _persistedExpiry(Object? value) => switch (value) {
  final int milliseconds => DateTime.fromMillisecondsSinceEpoch(
    milliseconds,
    isUtc: true,
  ),
  final String milliseconds when int.tryParse(milliseconds) != null =>
    DateTime.fromMillisecondsSinceEpoch(int.parse(milliseconds), isUtc: true),
  _ => null,
};

String generateChatGptPkceVerifier() {
  const alphabet =
      '[REDACTED:High Entropy String]._~';
  final random = _secureRandom();
  final bytes = Uint8List(96);
  for (var i = 0; i < bytes.length; i++) {
    bytes[i] = alphabet.codeUnitAt(random.nextInt(alphabet.length));
  }
  return String.fromCharCodes(bytes);
}

String generateChatGptPkceChallenge(String verifier) => base64UrlEncode(
  sha256.convert(utf8.encode(verifier)).bytes,
