      io.writeln(
        'fa: could not refresh the ChatGPT credential for '
        '"${entry.name}": ${error.message}\n'
        'The refresh token may be revoked (SSO/corporate session policy) — '
        're-authenticate with `/provider chatgpt oauth` and update the '
        'stored login.',
