/// the command targeted the flow.
bool _startDialSetupArg(List<String> args) {
  if (args.length < 2 || args[0] != 'dial' || args[1] != 'setup') {
    return false;
  }
  if (args.length > 2) {
    io.writeln('usage: /provider dial setup');
    return true;
  }
  unawaited(_startDialProviderSetup());
  return true;
}

