  Future<http.StreamedResponse> _request(
    ChatGptOAuthCredentials credentials,
  ) async {
    final uri = _endpoint;
    // Snapshot before the send/store sequence: `_learnedCookies()` must
    // diff against exactly what this request carried, never the post-store
    // jar of the same response.
    final cookieHeader = _cookies.cookieHeader(uri);
    _cookiesBeforeRequest = cookieHeader;
    final request = http.Request('POST', uri)
      ..headers.addAll({
        'content-type': 'application/json',
        'accept': 'text/event-stream',
        ...codexRequestHeaders(
          accessToken: [REDACTED:Sensitive Value],
          accountId: credentials.accountId,
          sessionId: _sessionId,
          threadId: _threadId,
        ),
        'cookie': ?cookieHeader,
        // Model headers go last so they can override the defaults.
        ...?model.headers,
      })
      ..body = jsonEncode(_requestBody());
    // Issue #1121 (review round 1): route through the SHARED watched send —
    // the hand-rolled `.timeout` below predated it, so a codex connect
    // stall got the watchdog but not the bounded zero-byte retry every
    // other adapter has, and a user abort during a wedged connect waited
    // out the full watchdog instead of propagating. Raw send (no
    // redirect/validity layer): Cloudflare cookies must be stored from
    // error responses too, and the challenge replay above owns that flow.
    final response = await sendWatchedProviderRequest(
      client,
      request,
      cancelToken,
      // Issue #1554: the model's request-scoped watchdog windows ride the
      // send — null falls through to the per-provider table, then global.
      // The scope label cites THE LEG THAT RAN: a model without a scoped
      // connect leg keeps the bare stall text (review round 1).
      connectTimeout: model.connectTimeout,
      timeoutSource: model.connectTimeout == null
          ? null
          : model.timeoutScopeLabel,
    );
    // Cloudflare sets its cookies even on error responses — store always.
    _cookies.store(uri, response.headers);
    return response;
  }

